+ cost
+
" | ETA: "
+ shipping.getEstimatedDelivery());
state.next(
this
);
// Transition from PAID to SHIPPED
}
public
void
deliver
()
{ state.next(
this
); }
public
void
cancel
()
{ state.cancel(
this
); }
public
String
getStatus
()
{
return
state.getStatus(); }
public
String
getOrderId
()
{
return
orderId; }
}
