final
int
cursorPosition;
private
final
long
timestamp;
public
EditorMemento
(String content,
int
cursorPosition)
{
this
.content = content;
this
.cursorPosition = cursorPosition;
this
.timestamp = System.currentTimeMillis();
}
public
String
getContent
()
{
return
content; }
public
int
getCursorPosition
()
{
return
cursorPosition; }
public
long
getTimestamp
()
{
return
