}
// Caretaker -- manages the history of mementos
public
class
EditorHistory
{
private
final
List<EditorMemento> undoStack =
new
ArrayList
<>();
private
final
List<EditorMemento> redoStack =
new
ArrayList
<>();
public
void
save
(EditorMemento memento)
{
undoStack.add(memento);
redoStack.clear();
// new action invalidates redo history
}
public
EditorMemento
undo
()
{
if
(undoStack.size() <=
1
)
return
null
;
// nothing to undo
EditorMemento
current
=
undoStack.remove(
undoStack.size() -
1
);
redoStack.add(current);
return
undoStack.get(undoStack.size() -
1
);
}
public
EditorMemento
redo
()
{
if
(redoStack.isEmpty())
return
null
;
EditorMemento
memento
=
redoStack.remove(
redoStack.size() -
1
);
undoStack.add(memento);
return
memento;
}
public
boolean
canUndo
()
{
return
undoStack.size() >
1
; }
public
boolean
canRedo
()
{
return
!redoStack.isEmpty(); }
