List<EditorCommand> commandLog;
public
TextEditor
()
{
this
.buffer =
new
TextBuffer
();
this
.history =
new
EditorHistory
();
this
.commandLog =
new
ArrayList
<>();
// Save initial state
history.save(
new
EditorMemento
(
buffer.getContent(), buffer.getCursorPosition()));
}
public
void
type
(String text)
{
EditorCommand
cmd
=
new
InsertCommand
(
buffer, text, buffer.getCursorPosition());
executeCommand(cmd);
}
public
void
deleteAt
(
int
position,
int
length)
{
EditorCommand
cmd
=
new
DeleteCommand
(
buffer, position, length);
executeCommand(cmd);
}
private
void
executeCommand
(EditorCommand cmd)
{
cmd.execute();
commandLog.add(cmd);
history.save(
new
EditorMemento
(
buffer.getContent(), buffer.getCursorPosition()));
System.out.println(
"Executed: "
+ cmd.getDescription());
}
public
void
undo
()
{
EditorMemento
memento
=
history.undo();
if
(memento!=
null
) {
buffer =
new
TextBuffer
();
buffer.insert(memento.getContent(),
0
);
buffer.setCursorPosition(memento.getCursorPosition());
System.out.println(
"Undo performed."
);
}
else
{
System.out.println(
"Nothing to undo."
);
}
public
void
redo
()
{
EditorMemento
memento
=
history.redo();
if
(memento!=
null
) {
buffer =
new
TextBuffer
();
buffer.insert(memento.getContent(),
0
);
buffer.setCursorPosition(memento.getCursorPosition());
System.out.println(
"Redo performed."
);
}
else
{
System.out.println(
"Nothing to redo."
);
}
public
String
getContent
()
{
return
buffer.getContent(); }
public
int
getCursorPosition
()
{
return
buffer.getCursorPosition(); }
}
