"resetLink"
) +
"\n"
+ message;
}
else
if
(templateName.equals(
"order_confirmation"
)) {
finalMessage =
"Dear "
+ params.get(
"name"
)
+
",\nYour order #"
+ params.get(
"orderId"
)
+
" has been confirmed.\nTotal: $"
+ params.get(
"total"
) +
"\n"
+ message;
}
else
if
(templateName.equals(
"shipping_update"
)) {
finalMessage =
"Dear "
+ params.get(
"name"
)
+
",\nYour order #"
+ params.get(
"orderId"
)
+
" has been shipped.\nTracking: "
+ params.get(
"trackingNumber"
) +
"\n"
+ message;
}
// Send based on type
if
(type.equals(
"email"
)) {
if
(urgent) {
