System.out.println(
"Message: "
+ smsMessage);
// Connect to SMS gateway, send...
System.out.println(
"SMS sent successfully."
);
}
else
if
(type.equals(
"push"
)) {
if
(urgent) {
System.out.println(
"[PUSH - HIGH PRIORITY] To: "
+ recipient);
}
else
{
System.out.println(
"[PUSH] To: "
+ recipient);
}
System.out.println(
"Title: "
+ subject);
String
pushBody
=
finalMessage.length() >
100
? finalMessage.substring(
0
,
97
) +
"..."
: finalMessage;
System.out.println(
"Body: "
+ pushBody);
// Connect to push service, send...
System.out.println(
"Push notification sent."
);
}
else
if
(type.equals(
"slack"
)) {
System.out.println(
"[SLACK] Channel: "
+ recipient);
String
slackMsg
=
"*"
+ subject +
"*\n"
+ finalMessage;
if
(urgent) {
slackMsg =
":rotating_light: "
+ slackMsg;
}
System.out.println(
"Message: "
+ slackMsg);
// Connect to Slack API, send...
System.out.println(
"Slack message sent."
);
}
// Log the notification
System.out.println(
"[LOG] "
+ type +
" notification sent to "
+ recipient +
" at "
+
new
java
.util.Date());
}
